def min_largest_sum(a, m):
    '''把 a 切成 m 段连续非空子数组，最小化最大段和。'''
    def pieces(limit):
        cnt, cur = 1, 0
        for v in a:
            if v > limit:
                return 10 ** 18
            if cur + v > limit:
                cnt += 1
                cur = v
            else:
                cur += v
        return cnt
    lo, hi = max(a), sum(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if pieces(mid) <= m:
            hi = mid
        else:
            lo = mid + 1
    return lo


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, m = data[0], data[1]
    a = data[2:2 + n]
    print(min_largest_sum(a, m))

