using int64 = long long;
// a 非递减，统计 i<j 且 a[i]+a[j]==target 的对数
int64 count_pairs(const vector<int64> &a, int64 target) {
 int i = 0, j = (int)a.size() - 1;
 int64 cnt = 0;
 while (i < j) {
 int64 s = a[i] + a[j];
 if (s < target) ++i;
 else if (s > target) --j;
 else {
 if (a[i] == a[j]) {
 int64 k = j - i + 1;
 cnt += k * (k - 1) / 2;
 break;
}
 int64 lv = a[i], rv = a[j];
 int64 c1 = 0, c2 = 0;
 while (a[i] == lv) { ++c1; ++i;}
 while (a[j] == rv) { ++c2; --j;}
 cnt += c1 * c2;
}
}
 return cnt;
}
int main() {
 ios::sync_with_stdio(false);
 cin.tie(nullptr);
 int n;
 int64 target;
 if (!(cin >> n >> target)) return 0;
 vector<int64> a(n);
 for (int i = 0; i < n; ++i) cin >> a[i];
 cout << count_pairs(a, target) << '\n';
 return 0;
}

