int64 count_subarrays(const vector<int64> &a, int64 k) {
 unordered_map<int64, int64> seen;
 seen.reserve(a.size() * 2);
 seen[0] = 1;
 int64 cur = 0, cnt = 0;
 for (int64 v: a) {
 cur += v;
