// 合并重叠区间，返回合并后的区间（按左端点排序）
vector<pair<int64,int64>> merge_intervals(vector<pair<int64,int64>> segs) {
    vector<pair<int64,int64>> res;
    if (segs.empty()) return res;
    sort(segs.begin(), segs.end());
    res.push_back(segs[0]);
    for (size_t i = 1; i < segs.size(); ++i) {
        if (segs[i].first <= res.back().second)
            res.back().second = max(res.back().second, segs[i].second);
        else
            res.push_back(segs[i]);
    }
    return res;
}
int main() {
