    for (int i = 0; i < n; ++i) cin >> segs[i].first >> segs[i].second;
    auto res = merge_intervals(segs);
    for (size_t i = 0; i < res.size(); ++i)
        cout << res[i].first << ' ' << res[i].second << '\n';
    return 0;
}

