import heapq


def max_profit(tasks):
    '''tasks 是 (deadline, profit)，每个任务耗时 1，求截止前能拿到的最大利润。'''
    tasks = sorted(tasks)
    heap = []
    for d, p in tasks:
        heapq.heappush(heap, p)
        if len(heap) > d:
            heapq.heappop(heap)
    return sum(heap)


if __name__ == '__main__':
