#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
// tasks 是 (deadline, profit)，每个任务耗时 1，求截止前最大利润
int64 max_profit(vector<pair<int,int64>> tasks) {
    sort(tasks.begin(), tasks.end());
    priority_queue<int64, vector<int64>, greater<int64>> heap;
    for (auto [d, p] : tasks) {
        heap.push(p);
        if ((int)heap.size() > d) heap.pop();
    }
    int64 ans = 0;
    while (!heap.empty()) { ans += heap.top(); heap.pop(); }
    return ans;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<pair<int,int64>> tasks(n);
    for (int i = 0; i < n; ++i) cin >> tasks[i].first >> tasks[i].second;
    cout << max_profit(tasks) << '\n';
    return 0;
}

