class ListNode:
    def __init__(self, v):
        self.val = v
        self.next = None


def build(vals, pos):
    '''vals 建链表；pos>=0 时尾节点连到第 pos 个节点（0-based），否则无环。'''
    if not vals:
        return None
    nodes = [ListNode(v) for v in vals]
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]
    if 0 <= pos < len(nodes):
        nodes[-1].next = nodes[pos]
    return nodes[0]


def has_cycle(head):
    '''快慢指针判环。'''
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    vals = data[1:1 + n]
    pos = data[1 + n]
    print('YES' if has_cycle(build(vals, pos)) else 'NO')

