    for (int i = 0; i + 1 < n; ++i) nodes[i]->next = nodes[i + 1];
    if (pos >= 0 && pos < n && n > 0) nodes.back()->next = nodes[pos];
    cout << (has_cycle(n ? nodes[0] : nullptr) ? "YES\n" : "NO\n");
    return 0;
}

