class TreeNode:
    def __init__(self, v):
        self.val = v
        self.left = None
        self.right = None


def build(n, info):
    '''info[i] = (val, left, right)，1-based 下标，0 表空；返回根（下标 1）。'''
    if n == 0:
        return None
    nodes = [None] + [TreeNode(info[i][0]) for i in range(1, n + 1)]
    for i in range(1, n + 1):
        _, l, r = info[i]
        if l:
            nodes[i].left = nodes[l]
        if r:
            nodes[i].right = nodes[r]
    return nodes[1]


def inorder(root):
    '''迭代中序遍历。'''
    res, st, cur = [], [], root
    while st or cur:
        while cur:
            st.append(cur)
            cur = cur.left
        cur = st.pop()
        res.append(cur.val)
        cur = cur.right
    return res


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    info = [None]
    pos = 1
    for _ in range(n):
        info.append((data[pos], data[pos + 1], data[pos + 2]))
        pos += 3
    print(' '.join(map(str, inorder(build(n, info)))))

