INF = 10 ** 18


def floyd(n, edges):
    '''多源最短路，返回 n×n 距离矩阵（0-based，不可达为 -1）。允许负权，无负环。'''
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for u, v, w in edges:
        if w < d[u][v]:
            d[u][v] = w
    for k in range(n):
        dk = d[k]
        for i in range(n):
            dik = d[i][k]
            if dik == INF:
                continue
            di = d[i]
            nd_base = dik
            for j in range(n):
                nd = nd_base + dk[j]
                if nd < di[j]:
                    di[j] = nd
    return [[-1 if x == INF else x for x in row] for row in d]


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, m = data[0], data[1]
    edges = []
    for i in range(m):
        u, v, w = data[2 + 3 * i], data[3 + 3 * i], data[4 + 3 * i]
        edges.append((u - 1, v - 1, w))
    out = floyd(n, edges)
    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in out))

