import bisect


def lis_length(a):
    '''最长递增子序列长度（严格递增），O(n log n)。'''
    tails = []
    for v in a:
        i = bisect.bisect_left(tails, v)
        if i == len(tails):
            tails.append(v)
        else:
            tails[i] = v
    return len(tails)


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    a = data[1:1 + n]
    print(lis_length(a))

