using namespace std;
// 最长递增子序列长度（严格递增），O(n log n)
int lis_length(const vector<int> &a) {
    vector<int> tails;
    for (int v : a) {
        auto it = lower_bound(tails.begin(), tails.end(), v);
        if (it == tails.end()) tails.push_back(v);
        else *it = v;
    }
    return (int)tails.size();
}
