def knapsack_01(n, W, items):
    '''0/1 背包：items 是 (重量, 价值)，容量 W，求最大价值。一维 DP 倒序。'''
    dp = [0] * (W + 1)
    for w, v in items:
        for c in range(W, w - 1, -1):
            if dp[c - w] + v > dp[c]:
                dp[c] = dp[c - w] + v
    return dp[W]


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, W = data[0], data[1]
    items = [(data[2 + 2 * i], data[3 + 2 * i]) for i in range(n)]
    print(knapsack_01(n, W, items))

