def merge_stones(a):
    '''相邻两堆合并，花费为两堆重量和，求合并成一堆的最小总花费。'''
    n = len(a)
    if n <= 1:
        return 0
    pre = [0]
    for v in a:
        pre.append(pre[-1] + v)

    def seg(i, j):
        return pre[j + 1] - pre[i]

    INF = 10 ** 18
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            best = INF
            for k in range(i, j):
                cost = dp[i][k] + dp[k + 1][j] + seg(i, j)
                if cost < best:
                    best = cost
            dp[i][j] = best
    return dp[0][n - 1]


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    a = data[1:1 + n]
    print(merge_stones(a))

