template_python:
def tsp(dist):
    '''n 个点对称距离矩阵，从 0 出发遍历所有点回到 0 的最短路。'''
    n = len(dist)
    if n == 1:
        return 0
    INF = 10 ** 18
    full = (1 << n) - 1
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0
    for mask in range(1 << n):
        for u in range(n):
            if dp[mask][u] == INF:
                continue
            for v in range(n):
                if mask >> v & 1:
                    continue
                nmask = mask | (1 << v)
                nd = dp[mask][u] + dist[u][v]
                if nd < dp[nmask][v]:
                    dp[nmask][v] = nd
    return min(dp[full][u] + dist[u][0] for u in range(n))


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    dist = [data[1 + i * n:1 + (i + 1) * n] for i in range(n)]
    print(tsp(dist))

template_cpp:
#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int64 INF = (int64)4e18;
// TSP：从 0 出发遍历所有点回到 0 的最短路
int64 tsp(const vector<vector<int64>> &dist) {
    int n = dist.size();
    if (n == 1) return 0;
    int full = (1 << n) - 1;
    vector<vector<int64>> dp(1 << n, vector<int64>(n, INF));
    dp[1][0] = 0;
    for (int mask = 0; mask <= full; ++mask)
        for (int u = 0; u < n; ++u) if (dp[mask][u] != INF)
            for (int v = 0; v < n; ++v) if (!(mask >> v & 1)) {
                int nmask = mask | (1 << v);
                dp[nmask][v] = min(dp[nmask][v], dp[mask][u] + dist[u][v]);
            }
    int64 ans = INF;
    for (int u = 0; u < n; ++u) ans = min(ans, dp[full][u] + dist[u][0]);
    return ans;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<vector<int64>> dist(n, vector<int64>(n));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) cin >> dist[i][j];
    cout << tsp(dist) << '\n';
    return 0;
}

