class DSU:
    def __init__(self, n):
        self.fa = list(range(n + 1))

    def find(self, x):
        while self.fa[x] != x:
            self.fa[x] = self.fa[self.fa[x]]
            x = self.fa[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.fa[rb] = ra
            return True
        return False


def mst(n, edges):
    '''Kruskal：返回最小生成树权值，不连通返回 -1。edges 是 (u,v,w)。'''
    dsu = DSU(n)
    total, cnt = 0, 0
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        if dsu.union(u, v):
            total += w
            cnt += 1
            if cnt == n - 1:
                break
    return total if cnt == n - 1 else -1


if __name__ == '__main__':
