using namespace std;
// 判断无向图是否是二分图，节点 1..n
bool is_bipartite(int n, const vector<pair<int,int>> &edges) {
    vector<vector<int>> g(n + 1);
    for (auto [u, v] : edges) { g[u].push_back(v); g[v].push_back(u); }
    vector<int> color(n + 1, 0);
    queue<int> q;
    for (int s = 1; s <= n; ++s) if (!color[s]) {
        color[s] = 1;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int w : g[u]) {
                if (!color[w]) { color[w] = 3 - color[u]; q.push(w); }
                else if (color[w] == color[u]) return false;
            }
        }
    }
    return true;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<pair<int,int>> edges(m);
    for (int i = 0; i < m; ++i) cin >> edges[i].first >> edges[i].second;
    cout << (is_bipartite(n, edges) ? "YES\n" : "NO\n");
    return 0;
}

