#include <bits/stdc++.h>
using namespace std;
// 返回 pat 在 text 中所有出现位置的起始下标（0-based）
vector<int> kmp_search(const string &text, const string &pat) {
    vector<int> res;
    int m = pat.size();
    if (m == 0) return res;
    vector<int> pi(m, 0);
    for (int i = 1; i < m; ++i) {
        int j = pi[i - 1];
        while (j > 0 && pat[i] != pat[j]) j = pi[j - 1];
        if (pat[i] == pat[j]) ++j;
        pi[i] = j;
    }
    int j = 0;
    for (int i = 0; i < (int)text.size(); ++i) {
        while (j > 0 && text[i] != pat[j]) j = pi[j - 1];
        if (text[i] == pat[j]) ++j;
        if (j == m) { res.push_back(i - m + 1); j = pi[j - 1]; }
    }
    return res;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string text, pat;
    getline(cin, text);
    getline(cin, pat);
    auto r = kmp_search(text, pat);
    for (int i = 0; i < (int)r.size(); ++i)
        cout << r[i] << (i + 1 == (int)r.size() ? '\n' : ' ');
    return 0;
}

