#include <bits/stdc++.h>
using namespace std;
struct Node {
    unordered_map<char,int> next;
    bool is_end = false;
};
struct Trie {
    vector<Node> t;
    Trie() { t.push_back(Node()); }
    void insert(const string &w) {
        int u = 0;
        for (char ch : w) {
            auto it = t[u].next.find(ch);
            if (it == t[u].next.end()) {
                t[u].next[ch] = t.size();
                t.push_back(Node());
            }
            u = t[u].next[ch];
        }
        t[u].is_end = true;
    }
    int walk(const string &w) const {
        int u = 0;
        for (char ch : w) {
            auto it = t[u].next.find(ch);
            if (it == t[u].next.end()) return -1;
            u = it->second;
        }
        return u;
    }
    bool search(const string &w) const {
        int u = walk(w);
        return u != -1 && t[u].is_end;
    }
    bool starts_with(const string &p) const { return walk(p) != -1; }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    if (!(cin >> q)) return 0;
    Trie trie;
    for (int i = 0; i < q; ++i) {
        int op; string w;
        cin >> op >> w;
        if (op == 1) trie.insert(w);
        else if (op == 2) cout << (trie.search(w) ? "YES\n" : "NO\n");
        else if (op == 3) cout << (trie.starts_with(w) ? "YES\n" : "NO\n");
    }
    return 0;
}

template_python:
def longest_palindrome(s):
    '''Manacher：返回最长回文子串（并列取起点最小）。'''
    if not s:
        return ''
    t = '#' + '#'.join(s) + '#'
    n = len(t)
    arm = [0] * n
    center = right = 0
    best_len, best_start = 1, 0
    for i in range(n):
        mirror = 2 * center - i
        if i < right:
            arm[i] = min(right - i, arm[mirror])
        while i - arm[i] - 1 >= 0 and i + arm[i] + 1 < n and t[i - arm[i] - 1] == t[i + arm[i] + 1]:
            arm[i] += 1
        if i + arm[i] > right:
            center, right = i, i + arm[i]
        cur_len = arm[i]
        cur_start = (i - arm[i]) // 2
        if cur_len > best_len or (cur_len == best_len and cur_start < best_start):
            best_len, best_start = cur_len, cur_start
    return s[best_start:best_start + best_len]


if __name__ == '__main__':
    import sys
    s = sys.stdin.read().strip().split('\n')[0] if sys.stdin else ''
    print(longest_palindrome(s))

