using int64 = long long;
struct Fenwick {
    int n;
    vector<int64> bit;
    Fenwick(int n = 0): n(n), bit(n + 1, 0) {}
    void add(int i, int64 v) {
        for (; i <= n; i += i & -i) bit[i] += v;
    }
    int64 prefix(int i) const {
        int64 s = 0;
        for (; i > 0; i -= i & -i) s += bit[i];
        return s;
    }
    int64 range_sum(int l, int r) const { return prefix(r) - prefix(l - 1); }
};
