def mod_mul(a, b, mod):
    '''(a*b) % mod，a、b 可达 1e18，Python 任意精度天然不溢出。'''
    return (a % mod) * (b % mod) % mod


def isqrt(n):
    '''整数平方根（向下取整），二分实现，中点防溢出写法。'''
    if n < 2:
        return n
    lo, hi = 1, n // 2
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        sq = mid * mid
        if sq == n:
            return mid
        if sq < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi


EPS = 1e-9


def feq(a, b):
    '''浮点相等比较：abs(a-b) <= EPS。'''
    return abs(a - b) <= EPS


